/**
 * Row types for the tables used so far.
 * Mirrors docs/TECH_AND_DATABASE.md (schema v2) and supabase/patches/*.
 * Replace with types generated by `supabase gen types typescript` once synced.
 */

export type Campus = {
  id: string;
  name: string;
  slug: string;
  domain: string;
  is_active: boolean;
};

export type Faculty = {
  id: string;
  campus_id: string;
  name: string;
  code: string | null;
};

export type Program = {
  id: string;
  campus_id: string;
  faculty_id: string | null;
  name: string;
  code: string;
  degree_level: string;
  is_pilot: boolean;
};

export type UserRole = "student" | "senior_contributor" | "curator" | "admin";

export type Profile = {
  id: string;
  campus_id: string | null;
  faculty_id: string | null;
  program_id: string | null;
  /** Privacy-friendly pseudonym. Never a real full name (UU PDP). */
  display_name: string;
  role: UserRole;
  semester: number | null;
  entry_year: number | null;
  adaptation_area: string | null;
  main_challenge: string | null;
  onboarding_completed: boolean;
};

export type ChecklistStatus = "pending" | "completed" | "skipped";

export type JourneyChecklistProgressRow = {
  id: string;
  user_id: string;
  area: string;
  checklist_item_id: string;
  status: ChecklistStatus;
  updated_at: string;
};

export type JourneyReflectionRow = {
  id: string;
  user_id: string;
  area: string;
  note: string;
  updated_at: string;
};

export type TaskPriority = "low" | "medium" | "high";
export type TaskCategory =
  | "social"
  | "academic"
  | "internship"
  | "scholarship"
  | "competition"
  | "personal";
export type TaskStatus = "todo" | "completed";

export type UserTaskRow = {
  id: string;
  user_id: string;
  title: string;
  description: string | null;
  due_date: string | null;
  priority: TaskPriority | null;
  category: TaskCategory;
  status: TaskStatus;
  journey_checklist_id: string | null;
  created_at: string;
  updated_at: string;
};
